const meta = {
  component: ToggleGroup,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Group two-state buttons that can each be toggled on or off.

**Import:** `@/registry/erbium/ui/toggle-group`

## Usage

```tsx
import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";
```

```tsx
<ToggleGroup>
  <ToggleGroupItem value="a">A</ToggleGroupItem>
  <ToggleGroupItem value="b">B</ToggleGroupItem>
  <ToggleGroupItem value="c">C</ToggleGroupItem>
</ToggleGroup>
```

## Composition

Use the following composition to build a `ToggleGroup`:

```text
ToggleGroup
├── ToggleGroupItem
└── ToggleGroupItem
```

## Changelog

Changed the default `spacing` from `0` to `2` so toggle groups render with space between items by default. Use `spacing={0}` for connected items.

Use `multiple` to allow more than one selected item. Controlled values are arrays passed through `value` and updated with `onValueChange`.

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Toggle](https://base-ui.com/react/components/toggle)
- [Toggle Group](https://base-ui.com/react/components/toggle-group)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof ToggleGroup>;

export default { ...meta, title: "Components/Toggle Group",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

